// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256 v) public {
        // Ensure the reference C can handle the input without reverting (it requires _tos.length > 0)
        vm.assume(_tos.length > 0);
        // Call transfer; it should not revert and return a boolean
        bool success;
        // We must catch revert to get a bool
        try c.transfer(from, caddress, _tos, v) returns (bool val) {
            success = val;
        } catch {
            // Reference should not revert, but if it does, set success to false to fail assertion
            success = false;
        }
        assertTrue(success, "transfer should return true for any non-empty array");
    }
}

